PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

select distinct ?person ?personLabel ?deathLabel ?coord where {
VALUES ?country { wd:Q34 } # If you want another country, put the country/countries you want to see in here
?person wdt:p1595|wdt:P7781|wdt:P1399 wd:Q259745 .
OPTIONAL { ?person wdt:P27 ?citizen }
OPTIONAL { ?person wdt:P509 ?death . }
OPTIONAL { ?person wdt:P20 ?deathplace . ?deathplace wdt:P17 ?c1 }
OPTIONAL { ?person wdt:P19 ?birth . ?birth wdt:P17 ?c2 }
BIND(IF(?c1 = ?country || ?c2 = ?country || ?citizen = ?country,?country,'') AS ?countrycheck)
FILTER (?countrycheck = ?country )
OPTIONAL { ?person wdt:P20 ?dp . ?dp wdt:P625 ?coord }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,sv." }
}

